# zero regions orthogonal connected to 6 marker
R,C=len(a),len(a[0]); q=deque(); seen=set()
for i in range(R):
 for j in range(C):
  if a[i][j]==6:
   for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
    x,y=i+di,j+dj
    if 0<=x<R and 0<=y<C and a[x][y]==0 and (x,y) not in seen: seen.add((x,y)); q.append((x,y))
while q:
 i,j=q.popleft()
 for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
  x,y=i+di,j+dj
  if 0<=x<R and 0<=y<C and a[x][y]==0 and (x,y) not in seen: seen.add((x,y));q.append((x,y))
out=[r[:] for r in a]
for i,j in seen: out[i][j]=6
print(len(seen), '\n'+'\n'.join(' '.join(map(str,r)) for r in out))

