for i in range(R-1):
 for j in range(C-1):
  if all(a[x][y]==0 for x,y in [(i,j),(i+1,j),(i,j+1),(i+1,j+1)]):
   for x,y in [(i,j),(i+1,j),(i,j+1),(i+1,j+1)]: b[x][y]=6
